return ['domain'=>'nitrosearch','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'ru_RU','project-id-version'=>'NitroSearch for WooCommerce','pot-creation-date'=>'2026-08-15T09:09:15+00:00','po-revision-date'=>'2026-08-08 16:58+0000','messages'=>['NitroSearch for WooCommerce'=>'NitroSearch for WooCommerce','https://nitrosearch.io'=>'https://nitrosearch.io','Blazing-fast hosted search for WooCommerce. Syncs your catalog to NitroSearch and replaces the default WordPress search with instant, typo-tolerant results.'=>'Молниеносный облачный поиск для WooCommerce. Синхронизирует ваш каталог с NitroSearch и заменяет стандартный поиск WordPress мгновенными результатами, устойчивыми к опечаткам.','WebDeviant'=>'WebDeviant','https://webdeviant.io'=>'https://webdeviant.io','<strong>NitroSearch now measures how your store\'s search performs</strong> — anonymous, cookieless counts of searches and result clicks, with no shopper identifiers. It helps result ranking improve, and per-store reporting is on the roadmap.'=>'<strong>Теперь NitroSearch измеряет, как работает поиск в вашем магазине</strong> — анонимный подсчёт поисковых запросов и кликов по результатам, без файлов cookie и идентификаторов покупателей. Это помогает улучшать ранжирование результатов, а отчёты по каждому магазину — в наших планах.','Manage it under %s.'=>'Управлять этим можно в разделе %s.','NitroSearch → Appearance'=>'NitroSearch → Внешний вид','Dismiss'=>'Скрыть','Unauthorized.'=>'Доступ запрещён.','Not connected'=>'Не подключено','Confirming control…'=>'Подтверждаем контроль…','Connected & verified'=>'Подключено и подтверждено','Amazon-quality search for WooCommerce'=>'Поиск уровня Amazon для WooCommerce','Connect your store'=>'Подключите свой магазин','Connect this store to NitroSearch to start syncing your catalog and serving instant, typo-tolerant search. Nothing leaves your site until you click Connect.'=>'Подключите этот магазин к NitroSearch, чтобы начать синхронизацию каталога и включить мгновенный, устойчивый к опечаткам поиск. Пока вы не нажмёте «Подключить магазин», данные не покидают ваш сайт.','Provisioning token'=>'Токен подключения','Optional. Only needed if you were given a token to connect this store.'=>'Необязательно. Нужен, только если вам выдали токен для подключения этого магазина.','Connect store'=>'Подключить магазин','Confirming control of your site…'=>'Подтверждаем контроль над вашим сайтом…','We’re verifying that you control this store before building your search index. In production this is automatic; if your site isn’t reachable from our servers it can take a moment. Your catalog syncs as soon as it’s confirmed.'=>'Прежде чем строить поисковый индекс, мы проверяем, что вы контролируете этот магазин. На рабочем сайте это происходит автоматически; если сайт недоступен с наших серверов, проверка может занять некоторое время. Каталог начнёт синхронизироваться сразу после подтверждения.','Check status'=>'Проверить статус','Disconnect'=>'Отключить','Dashboard'=>'Консоль','Design'=>'Дизайн','You’ve reached your plan’s limit.'=>'Достигнут лимит вашего тарифа.','Your search keeps running for everything already indexed, but new items won’t be added until you upgrade. Your products always take priority, so anything held back is a page or a post. Open %s below to move to a bigger plan.'=>'Поиск продолжает работать по всему, что уже проиндексировано, но новые элементы не будут добавляться, пока вы не повысите тариф. Ваши товары всегда в приоритете, поэтому под ограничение попадают только страницы и записи. Откройте %s ниже, чтобы перейти на более высокий тариф.','Manage / Upgrade'=>'Управление / Повышение тарифа','Sync health'=>'Состояние синхронизации','Search results indexed'=>'Проиндексировано результатов поиска','Unlimited'=>'Без ограничений','Pending changes'=>'Ожидающие изменения','Last sync'=>'Последняя синхронизация','Never'=>'Никогда','Last error'=>'Последняя ошибка','Sync all products'=>'Синхронизировать все товары','Refresh status'=>'Обновить статус','%s from now'=>'через %s','On demand'=>'По требованию','unit: millisecondsms'=>'мс','Sync performance'=>'Производительность синхронизации','Avg sync speed'=>'Средняя скорость синхронизации','Last batch'=>'Последний пакет','Items synced'=>'Синхронизировано элементов','Batches sent'=>'Отправлено пакетов','Next sync'=>'Следующая синхронизация','Changes to your catalog are batched and pushed in the background — these figures show how quickly they reach your search index.'=>'Изменения каталога собираются в пакеты и отправляются в фоновом режиме — эти цифры показывают, как быстро они попадают в поисковый индекс.','Search analytics'=>'Аналитика поиска','last 30 days'=>'за последние 30 дней','Couldn’t load analytics just now — it will retry automatically.'=>'Не удалось загрузить аналитику — повторная попытка будет выполнена автоматически.','<strong>%1$s</strong> on your store in the last 30 days. See what shoppers searched for, what they clicked, and what they looked for and didn’t find — included on every paid plan, from %2$s.'=>'<strong>%1$s</strong> в вашем магазине за последние 30 дней. Смотрите, что покупатели искали, на что нажимали и что искали, но не нашли, — доступно на каждом платном тарифе, от %2$s.','%s search'=>'%s поисковый запрос' . "\0" . '%s поисковых запроса' . "\0" . '%s поисковых запросов','%s/mo'=>'%s/мес.','Upgrade to unlock'=>'Повысьте тариф, чтобы открыть доступ','Analytics starts collecting with plugin 1.5.0+ active — data appears within a few hours of shoppers searching.'=>'Сбор аналитики начинается при активном плагине версии 1.5.0 или новее — данные появляются в течение нескольких часов после первых запросов покупателей.','Searches'=>'Поисковые запросы','Zero-result rate'=>'Доля запросов без результатов','Click-through'=>'Кликабельность','Top searches'=>'Популярные запросы','Searched, found nothing'=>'Искали, но не нашли','View full analytics →'=>'Смотреть полную аналитику →','Your plan & account'=>'Ваш тариф и учётная запись','This store is claimed to a NitroSearch account. Manage your plan and billing from your NitroSearch dashboard.'=>'Этот магазин привязан к учётной записи NitroSearch. Управляйте тарифом и оплатой из личного кабинета NitroSearch.','You\'re on the <strong>Free</strong> plan. Claim this store to a NitroSearch account to manage it or upgrade — your index and search stay exactly as they are.'=>'Вы используете <strong>бесплатный</strong> тариф. Привяжите этот магазин к учётной записи NitroSearch, чтобы управлять им или повысить тариф, — ваш индекс и поиск останутся ровно такими, как есть.','Roomy'=>'Просторный','Two-line names and a clear picture. The default.'=>'Названия в две строки и чёткое изображение. Вариант по умолчанию.','Compact'=>'Компактный','Smaller rows, so more products fit before scrolling.'=>'Строки меньше — до прокрутки помещается больше товаров.','Big pictures'=>'Крупные изображения','Larger thumbnails for image-led catalogs.'=>'Увеличенные миниатюры для каталогов, где главное — изображения.','Text only'=>'Только текст','No pictures — good for spare parts and B2B.'=>'Без изображений — подходит для запчастей, комплектующих и B2B.','Light'=>'Светлая','A white panel. Suits most themes.'=>'Белая панель. Подходит большинству тем.','Dark'=>'Тёмная','A dark panel, for dark headers and themes.'=>'Тёмная панель — для тёмных шапок и тем.','Automatic'=>'Автоматически','Follows each shopper\'s own device setting.'=>'Следует настройке устройства каждого покупателя.','Custom'=>'Пользовательская','Choose your own panel and text colors below.'=>'Выберите собственные цвета панели и текста ниже.','Look'=>'Оформление','Layout'=>'Макет','Products shown'=>'Показывать товаров','How many products appear in the drop-down as your shopper types.'=>'Сколько товаров появляется в выпадающем списке, пока покупатель вводит запрос.','Filters'=>'Фильтры','Automatic (recommended)'=>'Автоматически (рекомендуется)','Always across the top'=>'Всегда сверху','Hide in the drop-down'=>'Скрывать в выпадающем списке','In stock, on sale, brand and category filters. Automatic puts them in a side column when there is room, and across the top when there is not.'=>'Фильтры «В наличии», «Со скидкой», по бренду и категории. В режиме «Автоматически» они выводятся в боковой колонке, когда есть место, и сверху, когда его нет.','Drop-down width'=>'Ширина выпадающего списка','Wide'=>'Широкий','Match my search box'=>'По ширине поля поиска','Automatic gives product names enough room to read, even when your theme\'s search box is narrow. Match my search box keeps it exactly as wide as the box.'=>'Вариант «Автоматически» даёт названиям товаров достаточно места, даже если поле поиска вашей темы узкое. «По ширине поля поиска» делает список ровно такой же ширины, как само поле.','Colors'=>'Цвета','Color scheme'=>'Цветовая схема','Accent color'=>'Акцентный цвет','Used for prices, highlights and selected filters. Leave blank for the default. Text on top of it is set to black or white automatically, whichever stays readable.'=>'Используется для цен, подсветки и выбранных фильтров. Оставьте поле пустым, чтобы применялся цвет по умолчанию. Текст поверх него автоматически становится чёрным или белым — в зависимости от того, что лучше читается.','Panel background'=>'Фон панели','Only used when the color scheme is set to Custom.'=>'Используется, только если выбрана цветовая схема «Пользовательская».','Text color'=>'Цвет текста','Corners'=>'Углы','Rounded'=>'Скруглённые','Slightly rounded'=>'Слегка скруглённые','Square'=>'Прямые','Text style'=>'Стиль текста','Match my store'=>'Как в магазине','System default'=>'Системный шрифт','Custom font'=>'Свой шрифт','Match my store borrows the font your theme already uses around the search box.'=>'Вариант «Как в магазине» берёт шрифт, который ваша тема уже использует рядом с полем поиска.','example font stacke.g. Georgia, serif'=>'например: Georgia, serif','Only used when Custom font is selected.'=>'Используется, только если выбран вариант «Свой шрифт».','What to search'=>'Что искать','Include'=>'Включать','Products'=>'Товары','always indexed'=>'индексируются всегда','Pages'=>'Страницы','Blog posts'=>'Записи блога','Pages and posts count toward the same allowance as your products, so switching them off frees it up for your catalog. Your products always come first and are never displaced by them. Private, password-protected and unpublished content is never indexed, and we honor %s set by Yoast SEO or Rank Math (per item, per content type, or site-wide).'=>'Страницы и записи расходуют тот же лимит, что и товары, поэтому их отключение освобождает место для каталога. Товары всегда идут первыми и никогда ими не вытесняются. Личное, защищённое паролем и неопубликованное содержимое никогда не индексируется, а также мы учитываем %s, заданный в Yoast SEO или Rank Math (для отдельного элемента, типа содержимого или всего сайта).','Search results page'=>'Страница результатов поиска','Enhance the product search results page with NitroSearch results and filters'=>'Дополнять страницу результатов поиска товаров результатами и фильтрами NitroSearch','Privacy &amp; credit'=>'Конфиденциальность и упоминание','Search usage data'=>'Данные об использовании поиска','Share anonymous search usage counts with NitroSearch'=>'Передавать в NitroSearch анонимную статистику использования поиска','Counts searches, result totals and result clicks on your store\'s search — cookieless and anonymous, with no shopper identifiers, no IP addresses and nothing stored in the shopper\'s browser. Used to improve result ranking and to power your search analytics. Uncheck to stop sending immediately.'=>'Подсчитывает поисковые запросы, количество результатов и клики по результатам в поиске вашего магазина — анонимно и без файлов cookie: без идентификаторов покупателей, без IP-адресов и без сохранения чего-либо в браузере покупателя. Используется, чтобы улучшать ранжирование результатов и наполнять вашу аналитику поиска. Снимите флажок, чтобы немедленно прекратить отправку.','Powered-by credit'=>'Упоминание NitroSearch','Show a small “Powered by NitroSearch” credit, linking to nitrosearch.io'=>'Показывать небольшую надпись «Работает на NitroSearch» со ссылкой на nitrosearch.io','Off by default, and entirely your choice. Turning it on adds a small credit in the search box and one line in your site footer, both linking to %s — a normal, followed link. Nothing is added to your site unless you check this. Thank you if you do.'=>'По умолчанию выключено — решение полностью за вами. При включении в поле поиска появляется небольшая надпись, а в подвал сайта добавляется одна строка; обе ведут на %s обычной индексируемой ссылкой. Пока вы не установите флажок, на сайт ничего не добавляется. Если включите — спасибо.','Advanced'=>'Дополнительно','Search box selector'=>'Селектор поля поиска','example CSS selectore.g. input.my-theme-search'=>'например: input.my-theme-search','Optional CSS selector for your theme\'s search input. Leave blank to auto-detect.'=>'Необязательный CSS-селектор поля поиска вашей темы. Оставьте пустым для автоопределения.','Save design'=>'Сохранить дизайн','Connect failed: %s'=>'Не удалось подключиться: %s','unknown error'=>'неизвестная ошибка','Connected and verified.'=>'Подключено и подтверждено.','Connected. Confirming control of your site — this can take a moment. Use “Check status” below if it doesn’t update.'=>'Подключено. Подтверждаем контроль над вашим сайтом — это может занять некоторое время. Если статус не обновляется, нажмите «Проверить статус» ниже.','Syncing %s product in the background, then your pages and posts.'=>'Синхронизируем %s товар в фоновом режиме, затем ваши страницы и записи.' . "\0" . 'Синхронизируем %s товара в фоновом режиме, затем ваши страницы и записи.' . "\0" . 'Синхронизируем %s товаров в фоновом режиме, затем ваши страницы и записи.','Syncing %s product in the background.'=>'Синхронизируем %s товар в фоновом режиме.' . "\0" . 'Синхронизируем %s товара в фоновом режиме.' . "\0" . 'Синхронизируем %s товаров в фоновом режиме.','Verified!'=>'Подтверждено!','%1$s search results indexed · %2$s pending.'=>'Проиндексировано результатов поиска: %1$s · в очереди: %2$s.','Still confirming control of your site — please try again in a moment.'=>'Всё ещё подтверждаем контроль над вашим сайтом — повторите попытку чуть позже.','Design saved.'=>'Дизайн сохранён.','Saved. Removing your pages and blog posts from your index in the background.'=>'Сохранено. Удаляем ваши страницы и записи блога из индекса в фоновом режиме.','Saved. Removing your pages from your index in the background.'=>'Сохранено. Удаляем ваши страницы из индекса в фоновом режиме.','Saved. Removing your blog posts from your index in the background.'=>'Сохранено. Удаляем ваши записи блога из индекса в фоновом режиме.','Saved. Indexing your pages and blog posts in the background.'=>'Сохранено. Индексируем ваши страницы и записи блога в фоновом режиме.','Saved. Indexing your pages in the background.'=>'Сохранено. Индексируем ваши страницы в фоновом режиме.','Saved. Indexing your blog posts in the background.'=>'Сохранено. Индексируем ваши записи блога в фоновом режиме.','Disconnected.'=>'Отключено.','This store is already claimed to a NitroSearch account.'=>'Этот магазин уже привязан к учётной записи NitroSearch.','We couldn’t confirm control of your site yet — click "Refresh status" first, then try again.'=>'Нам пока не удалось подтвердить контроль над вашим сайтом — сначала нажмите «Обновить статус», затем повторите попытку.','Your site needs re-checking — click "Refresh status", then try again.'=>'Ваш сайт нужно проверить заново — нажмите «Обновить статус», затем повторите попытку.','Too many attempts — please wait a minute and try again.'=>'Слишком много попыток — подождите минуту и повторите попытку.','Could not create a manage link. Please try again.'=>'Не удалось создать ссылку для управления. Повторите попытку.','Insufficient permissions.'=>'Недостаточно прав.','Search powered by %s'=>'Поиск работает на %s','Refine results'=>'Уточнить результаты','Refine'=>'Уточнить','In stock'=>'В наличии','On sale'=>'Со скидкой','Brand'=>'Бренд','Category'=>'Категория','View'=>'Посмотреть','Add to cart'=>'В корзину','Adding…'=>'Добавляем…','Added ✓'=>'Добавлено ✓','Try again'=>'Повторить','Searching…'=>'Ищем…','Search is unavailable.'=>'Поиск недоступен.','Search is unavailable right now.'=>'Поиск сейчас недоступен.','No products found.'=>'Товары не найдены.','No products found for “%s”.'=>'По запросу «%s» товары не найдены.','Nothing found for “%s”.'=>'По запросу «%s» ничего не найдено.','Search products…'=>'Поиск товаров…','Close search'=>'Закрыть поиск','Product results'=>'Найденные товары','Recent searches'=>'Недавние запросы','Clear'=>'Очистить','Start typing to search products…'=>'Начните вводить запрос, чтобы найти товары…','Sale'=>'Скидка','Out of stock'=>'Нет в наличии','Pages & posts'=>'Страницы и записи','a website page, shown on a search resultPage'=>'Страница','a blog post, shown on a search resultArticle'=>'Статья','unit: milliseconds%s ms'=>'%s мс','Powered by %s'=>'Работает на %s','Page %1$s of %2$s'=>'Страница %1$s из %2$s','← Prev'=>'← Назад','Next →'=>'Вперёд →','button labelSearch'=>'Найти','%s product found.'=>'Найден %s товар.' . "\0" . 'Найдено %s товара.' . "\0" . 'Найдено %s товаров.','See all %s result →'=>'Показать %s результат →' . "\0" . 'Показать все %s результата →' . "\0" . 'Показать все %s результатов →','%1$s result for “%2$s”'=>'%1$s результат по запросу «%2$s»' . "\0" . '%1$s результата по запросу «%2$s»' . "\0" . '%1$s результатов по запросу «%2$s»','%s result'=>'%s результат' . "\0" . '%s результата' . "\0" . '%s результатов']];